3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode} before it is saved. The code is formatted
9	 * {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3} is the upper-cased first three letters of
10	 * the city, {@code LAST3} is the upper-cased first three letters of the last name and
11	 * {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the number of
12	 * owners already in that city (e.g. {@code LON-SMI-0007}). Mutates the entity in place so
13	 * {@link SaveOwner} persists it.
14	 */
15	public class AssignCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String city = owner.getCity();
19	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
20	        String lastName = owner.getLastName();
21	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
22	        long inCity = ownerRepository.findAll().stream()
23	                .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
24	                .count();
25	        long sequence = inCity + 1;
26	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
27	    }
28	}
