1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * Derives an owner's {@code checkDigit}: a single Luhn check digit (0-9) computed over the
5	 * digits contained in the owner's {@code customerCode}. Non-digit characters (the separators and
6	 * letters of a code such as {@code LON-SMI-0007}) are skipped, and the standard Luhn algorithm is
7	 * applied to the remaining digits, doubling every second digit from the right.
8	 */
9	public final class CheckDigit {
10	
11	    private CheckDigit() {
12	    }
13	
14	    /**
15	     * Returns the Luhn check digit (0-9) over the digits contained in {@code code}, or
16	     * {@code null} when {@code code} is {@code null}.
17	     */
18	    public static Integer luhnOf(String code) {
19	        if (code == null) {
20	            return null;
21	        }
22	        int sum = 0;
23	        boolean dbl = true;
24	        for (int i = code.length() - 1; i >= 0; i--) {
25	            char c = code.charAt(i);
26	            if (c < '0' || c > '9') {
27	                continue;
28	            }
29	            int d = c - '0';
30	            if (dbl) {
31	                d *= 2;
32	                if (d > 9) {
33	                    d -= 9;
34	                }
35	            }
36	            sum += d;
37	            dbl = !dbl;
38	        }
39	        return (10 - (sum % 10)) % 10;
40	    }
41	}
