15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class,
19	    imports = {org.springframework.samples.petclinic.util.LocalityResolver.class,
20	        org.springframework.samples.petclinic.util.MembershipLevel.class,
21	        org.springframework.samples.petclinic.util.ContactPreference.class,
22	        org.springframework.samples.petclinic.util.CheckDigit.class,
23	        org.springframework.samples.petclinic.rest.function.owner.OwnerIdentityKey.class})
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "displayName",
27	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
28	    @Mapping(target = "initials",
29	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
30	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
31	    @Mapping(target = "membershipLevel",
32	        expression = "java(MembershipLevel.levelOf(owner))")
33	    @Mapping(target = "locality",
34	        expression = "java(LocalityResolver.localityOf(owner.getPostcode(), owner.getCity()))")
35	    @Mapping(target = "contactPreference",
36	        expression = "java(ContactPreference.preferenceOf(owner))")
37	    @Mapping(target = "identityKey",
38	        expression = "java(OwnerIdentityKey.forOwner(owner))")
39	    @Mapping(target = "checkDigit",
40	        expression = "java(CheckDigit.luhnOf(owner.getCustomerCode()))")
41	    OwnerDto toOwnerDto(Owner owner);
42	
43	    Owner toOwner(OwnerDto ownerDto);
44	
45	    @Mapping(target = "id", ignore = true)
46	    @Mapping(target = "pets", ignore = true)
47	    Owner toOwner(OwnerFieldsDto ownerDto);
48	
49	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
50	
51	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
52	
53	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
54	        OwnerPageDto ownerPageDto = new OwnerPageDto();
55	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
56	        ownerPageDto.setPage(ownerPage.getNumber());
57	        ownerPageDto.setSize(ownerPage.getSize());
58	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
59	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
60	        return ownerPageDto;
61	    }
62	}
