1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerCityFullException;
8	
9	/**
10	 * Rejects a create-owner request whose city is already at capacity: a city that already contains
11	 * 50 or more owners cannot take another. The city is compared case-insensitively (matching how
12	 * {@link AssignCustomerCode} counts a city's owners). Runs after {@link ValidateNewOwner} has
13	 * published the request, and before {@link BuildOwner}, so a full city is a 409 rather than a
14	 * persisted record.
15	 */
16	public class CheckOwnerCityCapacity {
17	
18	    /** Maximum number of owners permitted in a single city. */
19	    private static final long CITY_CAPACITY = 50;
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws OwnerCityFullException {
23	        String city = request.getCity();
24	        long inCity = ownerRepository.findAll().stream()
25	                .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
26	                .count();
27	        if (inCity >= CITY_CAPACITY) {
28	            throw new OwnerCityFullException(city);
29	        }
30	    }
31	}
