1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
7	
8	/**
9	 * Shared derivation of an owner's {@code identityKey} — the single value that all duplicate
10	 * detection is now expressed through. The key is
11	 * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}, where:
12	 *
13	 * <ul>
14	 * <li>{@code normalizedTelephone} is the E.164 form (see {@link TelephoneE164});</li>
15	 * <li>the email component is the lower-cased email, or empty when none is supplied; and</li>
16	 * <li>{@code householdId} is the owner's shared household identifier (see {@link Household}), or
17	 *     empty when the owner belongs to no shared household.</li>
18	 * </ul>
19	 *
20	 * <p>Two owners are duplicates only when their <em>whole</em> keys are equal. Because the telephone
21	 * is part of the key, two members of the same household (same {@code householdId}) with different
22	 * telephones have different keys and are both allowed.
23	 */
24	public final class OwnerIdentityKey {
25	
26	    private OwnerIdentityKey() {
27	    }
28	
29	    /**
30	     * Identity key for an incoming create-owner request (after {@link ValidateNewOwner}). The
31	     * household component is the id the request would be assigned, so the key matches the one the
32	     * owner will carry once saved.
33	     */
34	    public static String forRequest(OwnerFieldsDto request, OwnerRepository ownerRepository) {
35	        return build(request.getTelephone(), request.getEmail(),
36	                Household.resolveId(request, ownerRepository));
37	    }
38	
39	    /** Identity key for an existing, stored owner. */
40	    public static String forOwner(Owner owner) {
41	        return build(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
42	    }
43	
44	    private static String build(String telephone, String email, String householdId) {
45	        return normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|"
46	                + (householdId == null ? "" : householdId);
47	    }
48	
49	    /** E.164 form when the value can form one, otherwise the raw value so it only matches itself. */
50	    private static String normalizeTelephone(String telephone) {
51	        if (telephone == null) {
52	            return "";
53	        }
54	        try {
55	            return TelephoneE164.normalize(telephone);
56	        }
57	        catch (InvalidTelephoneException ex) {
58	            return telephone;
59	        }
60	    }
61	
62	    /** Lower-cased email, or empty when none is supplied. */
63	    private static String normalizeEmail(String email) {
64	        if (email == null || email.isBlank()) {
65	            return "";
66	        }
67	        return email.trim().toLowerCase();
68	    }
69	}
