1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Out;
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.mapper.OwnerMapper;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	
11	public class BuildOwner {
12	
13	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
14	        Owner owner = ownerMapper.toOwner(request);
15	        LocalDate effective = owner.getRegistrationDate();
16	        if (effective == null) {
17	            effective = LocalDate.now();
18	        }
19	        // Registration must fall on a business day: a supplied or defaulted weekend date rolls
20	        // forward to the next Monday, and later steps derive their values from the adjusted date.
21	        owner.setRegistrationDate(BusinessDay.rollForward(effective));
22	        built.set(owner);
23	    }
24	}
