1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's {@code locality} (region). The postcode is preferred: a present,
7	 * well-formed postcode is matched against each region's fixed range (NSW 2000-2099,
8	 * VIC 3000-3099, QLD 4000-4099). Only when the postcode is absent or falls in no known
9	 * range does derivation fall back to a fixed city-to-region table. Anything the postcode
10	 * and city both fail to place derives the locality {@code "UNKNOWN"}.
11	 */
12	public final class LocalityResolver {
13	
14	    /** City -> canonical region. */
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	            "Sydney", "NSW",
17	            "Melbourne", "VIC",
18	            "Brisbane", "QLD");
19	
20	    /** Region -> inclusive 4-digit postcode range {low, high}. */
21	    private static final Map<String, int[]> REGION_RANGE = Map.of(
22	            "NSW", new int[] {2000, 2099},
23	            "VIC", new int[] {3000, 3099},
24	            "QLD", new int[] {4000, 4099});
25	
26	    /** The locality returned when neither postcode nor city places the owner. */
27	    public static final String UNKNOWN = "UNKNOWN";
28	
29	    private LocalityResolver() {
30	    }
31	
32	    /**
33	     * Returns the canonical region for {@code city}, or {@code "UNKNOWN"} when the
34	     * city (including {@code null}) is not in the table.
35	     */
36	    public static String localityOf(String city) {
37	        return CITY_REGION.getOrDefault(city, UNKNOWN);
38	    }
39	
40	    /**
41	     * Returns the canonical region, preferring {@code postcode}: when it is present and
42	     * falls in a known region's range that region wins. Otherwise the {@code city} table
43	     * decides, and failing that the locality is {@code "UNKNOWN"}. This returns the same
44	     * region for known cities but disambiguates cities that share a name.
45	     */
46	    public static String localityOf(String postcode, String city) {
47	        String fromPostcode = regionForPostcode(postcode);
48	        if (fromPostcode != null) {
49	            return fromPostcode;
50	        }
51	        return localityOf(city);
52	    }
53	
54	    /** The region whose range contains {@code postcode}, or {@code null} when absent/unplaced. */
55	    private static String regionForPostcode(String postcode) {
56	        if (postcode == null || postcode.isBlank()) {
57	            return null;
58	        }
