package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerCityFullException;

/**
 * Rejects a create-owner request whose city is already at capacity: a city that already contains
 * 50 or more owners cannot take another. The city is compared case-insensitively (matching how
 * {@link AssignCustomerCode} counts a city's owners). Runs after {@link ValidateNewOwner} has
 * published the request, and before {@link BuildOwner}, so a full city is a 409 rather than a
 * persisted record.
 */
public class CheckOwnerCityCapacity {

    /** Maximum number of owners permitted in a single city. */
    private static final long CITY_CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws OwnerCityFullException {
        String city = request.getCity();
        long inCity = ownerRepository.findAll().stream()
                .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
                .count();
        if (inCity >= CITY_CAPACITY) {
            throw new OwnerCityFullException(city);
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code membershipNumber} before it is saved. The number is formatted
 * {@code <customerCode>-M<YY>}, where {@code customerCode} is the owner's customer code and
 * {@code YY} is the last two digits of the {@code registrationDate} year, zero-padded
 * (e.g. {@code LON-SMI-0007-M26}). Runs after {@link AssignCustomerCode} has set the customer code
 * and {@link BuildOwner} has set the registration date, so both inputs are present. Mutates the
 * entity in place so {@link SaveOwner} persists it.
 */
public class AssignMembershipNumber {

    public void service(@Val Owner owner) {
        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
    }
}

package org.springframework.samples.petclinic.util;

/**
 * Derives an owner's {@code checkDigit}: a single Luhn check digit (0-9) computed over the
 * digits contained in the owner's {@code customerCode}. Non-digit characters (the separators and
 * letters of a code such as {@code LON-SMI-0007}) are skipped, and the standard Luhn algorithm is
 * applied to the remaining digits, doubling every second digit from the right.
 */
public final class CheckDigit {

    private CheckDigit() {
    }

    /**
     * Returns the Luhn check digit (0-9) over the digits contained in {@code code}, or
     * {@code null} when {@code code} is {@code null}.
     */
    public static Integer luhnOf(String code) {
        if (code == null) {
            return null;
        }
        int sum = 0;
        boolean dbl = true;
        for (int i = code.length() - 1; i >= 0; i--) {
            char c = code.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }
}

